/**
 * Season-to-season change of the fielding and keeping ratings. The parameters live in fielding-progression-model.ts
 * (generated by packages/ratings/src/analysis/fielding-progression.py from the Cricsheet fielding innings); this file
 * is the sampler. See docs/RATINGS-PIPELINE.md, "Fielding and keeping progression" and docs/RULES-SEASON.md section 7.
 *
 * A rating moves by  ageEffect(age) - reversion * (rating - 50) + sd * z,  z standard normal. The age effect is what
 * the fixed-effects fit of real player-seasons gives (fielding: flat to about 28, then -1.2 points a season); the
 * spread is small because the data find almost no persistent movement beyond the age curve; keeping is too noisy
 * to read off its own data and leans on the fielding decline.
 */

import { FIELDING_PROGRESSION, type FieldingProgressionFit } from "./fielding-progression-model.js";
import { interp, type ProgressionGender } from "./progression.js";
import { randomNormal } from "./math.js";
import type { RNG } from "./rng.js";

export type FieldingKind = "fielding" | "keeping";

/** The rating the pull-back works toward */
export const FIELDING_REVERSION_PIVOT = 50;

export function fieldingFit(kind: FieldingKind, gender: ProgressionGender): FieldingProgressionFit {
  return FIELDING_PROGRESSION[kind][gender];
}

/** Expected change over the coming season for a player who will be `ageNext` (age after the coming birthday), before luck */
export function expectedFieldingChange(kind: FieldingKind, rating: number, ageNext: number, gender: ProgressionGender = "male"): number {
  const fit = fieldingFit(kind, gender);
  return interp(fit.ageNodes, fit.ageEffect, ageNext) - fit.reversion * (rating - FIELDING_REVERSION_PIVOT);
}

/** One season's change (rating points, unrounded). `volatility` scales the luck (training intensity). Two RNG draws. */
export function sampleFieldingChange(
  kind: FieldingKind, rating: number, ageNext: number, gender: ProgressionGender, rng: RNG, volatility = 1,
): number {
  const fit = fieldingFit(kind, gender);
  return randomNormal(expectedFieldingChange(kind, rating, ageNext, gender), fit.sd * volatility, rng);
}
